rawdata = ""


import socket
# 服务器地址和端口
HOST = '192.168.115.155'
PORT = 443

client_hello_hex = rawdata
# 将十六进制字符串转换为字节
client_hello_bytes = bytes.fromhex(client_hello_hex)
# 发送ClientHello消息到服务器的函数
def send_client_hello(server_ip, server_port, client_hello_packet):
    # 创建socket对象
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
        # 连接到服务器
        s.connect((server_ip, server_port))
        # 发送ClientHello消息
        s.sendall(client_hello_packet)
